window.OL_I18N = {"lang":"nl","dict":{"meta.appName":"Openline eSIM-compatibiliteitscheck","meta.searchTitle":"{q} eSIM-compatibiliteit · Openline","ui.skip":"Ga naar de inhoud","ui.brandAria":"Openline — Controleer of je apparaat compatibel is","ui.brandSub":"Controleer of je apparaat compatibel is","lang.label":"Taal","lang.aria":"Taal wijzigen","hero.titleHtml":"Ondersteunt jouw apparaat <span class=\"accent\">eSIM</span>?","hero.tag":"Telefoon, tablet, smartwatch of hotspot — typ een merk of model en we laten je direct weten of Openline erop werkt.","search.placeholder":"Probeer “iPhone 18 Pro”, “Galaxy Z Fold8”, “Pixel Watch 5”, “iPad Air” of een modelnummer…","search.aria":"Zoek een apparaat op merk, model of modelnummer","search.clear":"Zoekopdracht wissen","stats.devices":"apparaten","stats.compatible":"compatibel","stats.notCompatible":"niet compatibel","stats.brands":"merken","filters.label":"Filters","filters.summaryAll":"Alle apparaten · Alle merken","filters.explain":"Kies een compatibiliteitsstatus en/of een of meer merken. Filters werken samen met het zoekveld en passen de lijst hieronder direct aan.","filters.compat":"Compatibiliteit","filters.compatAria":"Compatibiliteitsfilters","filters.brands":"Merken","filters.brandsAria":"Merkfilters","filters.clearAll":"Alles wissen","filters.compatOnly":"Alleen compatibel","filters.notCompatOnly":"Alleen niet compatibel","filters.allStatuses":"Alle statussen","filters.nBrands":{"one":"{n} merk","other":"{n} merken"},"filters.matchHtml":{"one":"<strong>{n}</strong> apparaat gevonden","other":"<strong>{n}</strong> apparaten gevonden"},"cat.count":{"one":"{n} apparaat","other":"{n} apparaten"},"results.all":"Alle apparaten","results.matching":"Overeenkomende apparaten","results.ofTotalHtml":"<strong>{n}</strong> van {total}","results.totalHtml":"<strong>{n}</strong> in totaal","results.showingFirst":" · eerste {max} getoond","legend.ok":"eSIM ondersteund","legend.err":"Alleen fysieke SIM","status.ok":"Compatibel","status.no":"Niet compatibel","status.okAria":"Compatibel met eSIM","status.noAria":"Niet compatibel met eSIM","note.caveatAria":"Regionale uitzondering: {note}","popover.aria":"Regionale uitzondering","popover.close":"Sluiten","empty.noMatchTitle":"Geen exacte overeenkomst.","empty.noMatchBodyHtml":"Probeer alleen het merk (bijv. <em>Samsung</em>) of het exacte modelnummer (bijv. <em>SM-S921B</em>). Als je apparaat van na 2021 is en buiten het vasteland van China is uitgebracht, is de kans zeer groot dat het eSIM ondersteunt.","empty.bothTitle":"Geen apparaten gevonden die bij je zoekopdracht en filters passen.","empty.bothBodyHtml":{"one":"Je zoekopdracht naar <em>{q}</em> levert in totaal <strong>{n}</strong> apparaat op, maar dat past niet bij je huidige filters. Misschien zorgen je filters voor het conflict?","other":"Je zoekopdracht naar <em>{q}</em> levert in totaal <strong>{n}</strong> apparaten op, maar geen ervan past bij je huidige filters. Misschien zorgen je filters voor het conflict?"},"empty.filtersTitle":"Geen apparaten gevonden voor deze filters.","empty.filtersBody":"Probeer je filters te versoepelen — een zeldzame status combineren met weinig merken kan niets opleveren.","empty.nothing":"Hier is nog niets te zien.","empty.resetFilters":"Filters resetten","empty.clearSearch":"Zoekopdracht wissen","footer.privacy":"Privacy","footer.terms":"Voorwaarden","footer.socialAria":"Openline op sociale media","footer.onNetwork":"Openline op {network}","footer.handleOnNetwork":"@askopenline op {network}","footer.indexedHtml":"<b id=\"footer-total\">{n}</b> apparaten geïndexeerd","region.US":"Verenigde Staten","region.HK":"Hongkong","region.CN":"vasteland van China","region.KR":"Zuid-Korea","region.JP":"Japan","region.AU":"Australië","region.TW":"Taiwan","region.SEA":"Zuidoost-Azië","region.EU":"Europese Unie","region.IN":"India","region.UK":"Verenigd Koninkrijk","exp.carrierWatch":"Smartwatches met mobiel netwerk krijgen hun eSIM via een watch-abonnement van je provider, in te stellen via de app op de gekoppelde telefoon (Apple Watch-app, Galaxy Wearable, Pixel Watch-app). QR-codes voor telefoon- of reis-eSIM's kunnen niet rechtstreeks op het horloge worden geïnstalleerd, dus controleer of je provider een abonnement voor dit horloge aanbiedt.","exp.gpsOnly":"Dit is de versie met alleen GPS. Deze heeft geen mobiele modem en kan dus geen eSIM gebruiken. De GPS + Cellular-versie van hetzelfde horloge heeft een ander modelnummer.","exp.cnHkMoDualNano":"iPhones van deze generatie die op het vasteland van China, in Hongkong en Macau zijn verkocht, hebben twee fysieke nano-SIM-slots en geen eSIM. Openline kan niet op deze toestellen worden geïnstalleerd. Controleer het modelnummer via Instellingen › Algemeen › Info.","exp.cnDualNano":"De versie van deze telefoon voor het vasteland van China gebruikt twee fysieke nano-SIM-kaarten en heeft geen eSIM. Modellen die elders zijn verkocht ondersteunen wel eSIM. Controleer het modelnummer via Instellingen › Algemeen › Info.","exp.cnLocalRules":"De versie voor het vasteland van China ondersteunt eSIM, maar Chinese providers activeren eSIM's alleen in hun winkels na een identiteitscontrole, en buitenlandse eSIM-profielen kunnen niet worden geïnstalleerd zolang je op het vasteland van China bent. Buiten China werken reis-eSIM's zoals Openline gewoon.","exp.esimOnlyUsJpCaGulf":"Toestellen die in de Verenigde Staten, Canada, Japan, Mexico en de Golfstaten zijn verkocht, hebben geen SIM-lade en werken uitsluitend met eSIM. Elders heeft de telefoon ook een nano-SIM-lade, en toestellen voor het vasteland van China hebben mogelijk geen eSIM. Openline werkt op elke versie met eSIM.","exp.noSimTray":"Deze versie heeft geen fysieke SIM-lade: elke lijn, ook Openline, wordt als eSIM toegevoegd. Je kunt meerdere eSIM's opslaan en via Instellingen tussen ze wisselen.","exp.iden":"Dit apparaat werkt op het iDEN-netwerk van Motorola (Nextel / Boost push-to-talk), dat Sprint in juni 2013 volledig heeft uitgeschakeld. Het kan geen verbinding maken met een modern mobiel netwerk — met of zonder eSIM. Alleen interessant voor musea en verzamelaars.","exp.cdmaVerizon":"Dit is een apparaat met uitsluitend CDMA, gemaakt voor het oude 2G/3G CDMA-netwerk van Verizon, dat op 31 december 2022 is uitgeschakeld. Het heeft helemaal geen SIM-slot (fysiek noch eSIM) — CDMA authenticeert op het netwerk via het ESN/MEID van het apparaat, niet via een SIM. Het kan niet worden gebruikt met Openline of een andere moderne provider.","exp.cdmaSprint":"Dit is een CDMA-apparaat gemaakt voor het oude netwerk van Sprint, dat T-Mobile op 31 mei 2022 definitief heeft uitgeschakeld. Nieuwere Sprint-modellen kregen LTE/GSM, maar eerdere zijn uitsluitend CDMA en kunnen met geen enkel modern netwerk verbinden — met of zonder eSIM.","exp.sunset":"Dit apparaat is afhankelijk van 3G- of oudere 4G-netwerken die providers hebben uitgeschakeld (AT&T 3G eindigde in februari 2022, T-Mobile in februari 2022, Verizon in december 2022, de meeste Europese 3G-netwerken uiterlijk 2025). Zelfs met een werkend SIM-slot is er in de meeste landen geen netwerk om mee te verbinden.","exp.windowsPhone":"Dit toestel draait op Windows Phone (of Windows 10 Mobile), waarvan Microsoft de ondersteuning in 2019 heeft stopgezet — de Store, beveiligingsupdates en de meeste eigen diensten zijn uitgeschakeld. Het heeft geen eSIM-hardware en vrijwel geen ondersteuning voor moderne apps. Niet bruikbaar als dagelijkse telefoon.","exp.kaios":"Dit is een KaiOS feature phone. Vrijwel geen enkel KaiOS-apparaat ondersteunt eSIM — ze gebruiken een fysieke SIM (meestal nano-SIM) en zijn bedoeld voor goedkope feature-phonemarkten met alleen 4G, zoals India (JioPhone) en Afrika. Openline kan hierop niet worden geïnstalleerd.","exp.telematics":"Dit is een telematicamodule voor voertuigen (Tesla, BMW, Audi, enz.) met een af fabriek ingebouwde eSIM die op het connectiviteitsbord van de auto is gesoldeerd. De eSIM wordt in de fabriek door de autofabrikant ingericht en kan niet worden vervangen door een door de gebruiker geïnstalleerd profiel zoals Openline. Niet door de gebruiker te onderhouden.","exp.satellite":"Dit is een satelliet-/GPS-communicator (Garmin inReach, SPOT, Zoleo, Iridium GO) die het Iridium- of Globalstar-satellietnetwerk gebruikt — geen GSM/LTE. Het kan geen eSIM in de gebruikelijke zin gebruiken; de verbinding is gekoppeld aan een eigen abonnement bij de fabrikant van de tracker.","exp.medical":"Dit is een medisch alarmapparaat of PERS-apparaat (personal emergency response). De mobiele modem is vergrendeld op de dienstverlener (Lively, Medical Guardian, Life Alert, Bay Alarm) en werkt alleen met hun meldkameraanbod. Er kunnen geen eSIM's van derden op worden geïnstalleerd.","exp.rugged":"Dit is een Samsung Enterprise / Rugged-apparaat (Galaxy XCover-serie) voor medewerkers in het veld — magazijnen, zorg, horeca. Het ondersteunt eSIM, maar activering kan via de Samsung Knox MDM-configuratie van je werkgever lopen. Openline installeert zoals op elke consumententelefoon, mits het apparaat simlockvrij is.","exp.harmony":"Dit apparaat draait op HarmonyOS (Huawei) zonder Google Mobile Services. Voor eSIM-activatie is meestal de carrier-services-app van Huawei EMUI/HarmonyOS nodig; Openline-profielen worden via de QR-code ingericht, maar activering via Google Wallet werkt niet. Toestellen die op het vasteland van China zijn verkocht, kunnen internationale eSIM-profielen bovendien weigeren vanwege beperkingen in de Chinese firmware.","exp.dualEsimOnly":"Deze variant ondersteunt twee eSIM's tegelijk, maar heeft geen fysieke SIM-lade. Openline werkt — je kunt het alleen niet combineren met een nano-SIM. Op sommige regionale versies kan slechts één eSIM tegelijk actief zijn.","exp.euCarrier":"Sommige Europese provider-gebonden varianten van dit toestel zijn geleverd met eSIM uitgeschakeld op firmwareniveau. Simlockvrije/internationale modellen ondersteunen eSIM normaal. Neem contact op met je oorspronkelijke provider als activering mislukt.","exp.usCarrier":"Dit is een variant van een Amerikaanse provider (AT&T, T-Mobile, Verizon, Sprint) met vergrendelde firmware en vaak providerspecifieke bandondersteuning. eSIM kan zijn uitgeschakeld of beperkt tot profielen van de provider van die variant. Simlockvrije internationale toestellen van hetzelfde model werken doorgaans met Openline; toestellen van een provider mogelijk niet.","exp.verizon":"Bij Verizon-toestellen van deze Pixel was eSIM bij de lancering uitgeschakeld op het netwerk van Verizon. Simlockvrije toestellen en toestellen van andere providers ondersteunen eSIM normaal.","exp.googleFi":"Bij deze generatie Pixel was eSIM in de VS alleen beschikbaar via Google Fi. Andere providers gebruikten alleen een fysieke SIM. Wereldwijde simlockvrije toestellen ondersteunen eSIM overal.","exp.usEsimOnly":"Bij in de VS gekochte exemplaren van deze iPhone heeft Apple de fysieke SIM-lade helemaal weggelaten — je moet een eSIM gebruiken. Overal elders heeft de telefoon naast eSIM ook een fysieke SIM-lade. Openline werkt in beide gevallen.","exp.cnOnly":"Dit apparaat wordt geleverd met firmware voor de Chinese markt. eSIM-ondersteuning is er op papier, maar internationale profielen kunnen buiten het vasteland van China vaak niet worden geactiveerd. Als je van plan bent te reizen, vraag dan vóór aankoop aan de verkoper of eSIM-activering werkt.","exp.jpDomestic":"Telefoons van Japanse providers (NTT DoCoMo, au, SoftBank, Rakuten) zijn meestal vergrendeld op het frequentieplan van Japan. De eSIM-hardware werkt in Japan; activering in het buitenland hangt af van de overlap in frequenties met lokale netwerken.","exp.regionLocked":"De eSIM-activering van dit apparaat is op firmwareniveau regiogebonden. Het accepteert alleen eSIM-profielen van providers in het land of de regio waar het is verkocht.","exp.krOnly":"Dit model wordt alleen in Zuid-Korea verkocht en gebruikt de frequenties van KT/SKT/LGU+. eSIM-hardware is aanwezig, maar activering in het buitenland is onbetrouwbaar.","exp.foldable":"Dit is een opvouwbaar toestel — de eSIM is aanwezig, maar let op: sommige in China verkochte opvouwbare varianten missen ondersteuning voor internationale eSIM's. Controleer of de modelcode overeenkomt met de wereldwijde SKU.","exp.hotspot":"Dit is een draagbare wifi-hotspot / MiFi-router en geen telefoon. Hij accepteert een eSIM om mobiele data te delen met je andere apparaten. Openline wordt op dezelfde manier ingericht als op een telefoon.","exp.simTrayOnly":"Dit apparaat heeft een mobiele modem, maar accepteert alleen een fysieke nano-SIM of micro-SIM — er is geen eSIM-chip. Je kunt Openline hier niet als eSIM installeren; je hebt een abonnement met fysieke SIM nodig.","exp.wifiOnly":"Deze variant heeft alleen Wi-Fi — geen mobiele modem. Er kan geen eSIM op worden geïnstalleerd. Zoek de LTE / 5G / Cellular-versie van hetzelfde model.","exp.ereader":"Dit is een e-reader met een af fabriek ingebouwde mobiele modem die gekoppeld is aan het gratis dataplan van de fabrikant (Amazon Whispernet, B&N nook, enz.). De eSIM/SIM kan niet door de gebruiker worden ingericht — je kunt geen Openline-profiel toevoegen.","exp.cellularEsimOnly":"Deze variant heeft mobiel netwerk alleen via eSIM — het apparaat heeft geen fysieke SIM-lade. Openline installeert direct via QR-code.","exp.unverifiedVariant":"Volgens onze gegevens is deze modelcode gekoppeld aan meer dan één productfamilie. Dat betekent meestal dat Apple/Samsung/Google een intern nummer voor meerdere generaties heeft gebruikt, of dat een regionale SKU een andere naam kreeg. Openline zou nog steeds moeten werken, maar als het modelnummer op de doos niet overeenkomt met het apparaat dat je bekijkt, controleer het dan vóór aankoop bij de fabrikant.","exp.crossBrand":"Deze modelcode komt ook voor bij een apparaat van een ander merk (Vivo/iQOO, Xiaomi/POCO, Nokia/HMD, Nubia/ZTE enz.). Meestal is dat een zustermerk — de hardware is vaak identiek, soms onder een andere naam — maar eSIM-ondersteuning en providercertificering kunnen per merk verschillen. Controleer dit aan de hand van de originele verpakking van je toestel.","exp.modelUnverified":"We hebben geen officieel model- of onderdeelnummer van dit apparaat — meestal omdat het een wearable, telematicamodule voor voertuigen, hotspot of accessoire is waarvan de SKU niet openbaar is. eSIM-ondersteuning staat in de specificaties van de fabrikant, maar Openline kan geen specifieke hardwarecode koppelen om compatibiliteit te garanderen. Controleer het bij de fabrikant voordat je erop vertrouwt.","exp.ambiguous":"De productnaam is hier erg kort (“13”, “F7”, “M6”…) en makkelijk te verwarren met modellen met hetzelfde nummer van andere merken of generaties. Controleer het merk en de modelcode op je apparaat om zeker te weten dat dit item overeenkomt met wat je hebt.","exp.cnFirmware":"Dit toestel wordt geleverd met firmware voor de Chinese markt. eSIM-hardware is aanwezig, maar de Chinese firmware blokkeert vaak de activering van internationale eSIM-profielen. Als je Openline buiten het vasteland van China wilt gebruiken, controleer dan vóór aankoop bij de verkoper dat de firmware niet regiogebonden is.","exp.regionExcluded":"Exemplaren van dit apparaat die in de volgende regio's zijn verkocht, hebben geen eSIM-hardware, dus alleen de fysieke SIM-lade werkt: {regions}. Overal elders wordt eSIM ondersteund en werkt Openline normaal. Als je het toestel in het buitenland of via een parallelimporteur hebt gekocht, vergelijk dan het modelnummer met de lijst van de fabrikant.","note.3G free":"Zonder 3G","note.3G/4G":"3G/4G","note.AU/JP/TW excluded":"AU/JP/TW uitgesloten","note.Ambiguous name":"Dubbelzinnige naam","note.CDMA":"CDMA","note.CN firmware":"CN-firmware","note.CN/HK excluded":"CN/HK uitgesloten","note.CN/HK/MO: dual nano-SIM":"CN/HK/MO: dual nano-SIM","note.CN/IN":"CN/IN","note.CN/IN dual-eSIM only":"CN/IN alleen dual-eSIM","note.CN: dual nano-SIM":"CN: dual nano-SIM","note.CN: local eSIM rules":"CN: lokale eSIM-regels","note.Carrier watch plan":"Watch-abonnement provider","note.Cross-brand model code":"Merkoverschrijdende modelcode","note.E-reader":"E-reader","note.Enterprise rugged":"Zakelijk robuust","note.Foldable":"Opvouwbaar","note.GPS only":"Alleen GPS","note.GPS/satellite tracker":"GPS-/satelliettracker","note.Google Fi/US only":"Alleen Google Fi/US","note.HarmonyOS":"HarmonyOS","note.JP domestic band lock":"JP-bandvergrendeling","note.KR only":"Alleen KR","note.KR/CN":"KR/CN","note.KaiOS feature phone":"KaiOS feature phone","note.Medical alert":"Medisch alarm","note.Mobile hotspot":"Mobiele hotspot","note.Model code unverified":"Modelcode niet geverifieerd","note.Nextel/Boost":"Nextel/Boost","note.No eSIM hardware":"Geen eSIM-hardware","note.No eSIM in most regions":"Meestal geen eSIM","note.Not on Verizon/Sprint":"Niet op Verizon/Sprint","note.SEA excluded":"SEA uitgesloten","note.SIM tray only":"Alleen SIM-lade","note.Sprint":"Sprint","note.US carrier variant":"US-providervariant","note.US model excluded":"US-model uitgesloten","note.US variant excluded":"US-variant uitgesloten","note.US/HK excluded":"US/HK uitgesloten","note.US/JP: eSIM ok":"US/JP: eSIM ok","note.US: eSIM only":"US: alleen eSIM","note.Unverified variant":"Niet-geverifieerde variant","note.Vehicle telematics":"Voertuigtelematica","note.Verizon":"Verizon","note.Verizon US no eSIM":"Verizon US geen eSIM","note.Verizon-only 5G":"5G alleen Verizon","note.Wi-Fi + Cellular only":"Alleen Wi-Fi + Cellular","note.Wi-Fi + free 4G":"Wi-Fi + gratis 4G","note.Wi-Fi only":"Alleen Wi-Fi","note.Wi-Fi only in most regions":"Meestal alleen Wi-Fi","note.Wi-Fi/3G":"Wi-Fi/3G","note.Windows Phone":"Windows Phone","note.deprecated":"verouderd","note.dual-eSIM in EU":"dual-eSIM in EU","note.eSIM only":"Alleen eSIM","note.eSIM only (no SIM tray)":"Alleen eSIM (geen SIM-lade)","note.eSIM only in US/JP/CA/Gulf":"Alleen eSIM in US/JP/CA/Golfstaten","note.eSIM only via Google Fi":"Alleen eSIM via Google Fi","note.iDEN":"iDEN","note.sunset":"uitgefaseerd"}};
